solutions.naive:
class Solution:
    def lengthOfLongestSubstringKDistinct(self, s: str, k: int) -> int:
        best = 0
        for left in range(len(s)):
            seen = set()
            for right in range(left, len(s)):
                seen.add(s[right])
                if len(seen) > k:
                    break
                best = max(best, right - left + 1)
        return best

solutions.better:
class Solution:
    def lengthOfLongestSubstringKDistinct(self, s: str, k: int) -> int:
        if k == 0:
            return 0
        last = {}
        left = best = 0
        for right, ch in enumerate(s):
            last[ch] = right
            if len(last) > k:
                drop = min(last, key=last.get)
                left = last[drop] + 1
                del last[drop]
            best = max(best, right - left + 1)
        return best

